/** Stateless Shell HTTP calls. Each call owns its request or event stream. */
export function createStatusClient({origin,nonce,fetch:request=globalThis.fetch,timeoutMs=30000,onSlow}={}) {
  const headers={Origin:origin,...(nonce?{'X-FinSAFE-Instance':nonce}:{})};
  async function read(path) {
    const controller=new AbortController();
    const timeout=setTimeout(()=>controller.abort(Error('Shell status read timed out')),timeoutMs);
    const notice=setTimeout(()=>{try{onSlow?.(path);}catch{}},5000);
    try {
      const response=await request(origin+path,{method:'GET',redirect:'error',cache:'no-store',headers,signal:controller.signal});
      const value=await response.json();
      if(!response.ok)throw Object.assign(Error(value.detail??value.error??`Shell HTTP ${response.status}`),
        {status:response.status,code:value.code,resource:value.resource??path});
      return value;
    } catch(error) {
      if(controller.signal.aborted)throw controller.signal.reason;
      throw error;
    } finally {clearTimeout(timeout);clearTimeout(notice);}
  }
  function subscribe(onResource,{onError=()=>{}}={}) {
    const controller=new AbortController();
    void (async()=>{
      const response=await request(origin+'/api/events',{method:'GET',redirect:'error',cache:'no-store',headers,signal:controller.signal});
      if(!response.ok)throw Error(`Shell event subscription failed: ${response.status}`);
      const decoder=new TextDecoder();let buffer='';
      for await(const chunk of response.body) {
        buffer=(buffer+decoder.decode(chunk,{stream:true})).replaceAll('\r\n','\n');
        if(buffer.length>16384)throw Error('Shell event exceeds 16 KiB');
        let end;
        while((end=buffer.indexOf('\n\n'))>=0) {
          const lines=buffer.slice(0,end).split('\n');buffer=buffer.slice(end+2);
          const event=lines.find(line=>line.startsWith('event:'))?.slice(6).trim();
          if(event==='resync')onResource(undefined);
          if(event==='resource_changed') {
            const data=lines.filter(line=>line.startsWith('data:')).map(line=>line.slice(5).trim()).join('\n');
            onResource(JSON.parse(data).resource);
          }
        }
      }
      if(!controller.signal.aborted)throw Error('Shell event subscription ended');
    })().catch(error=>{if(!controller.signal.aborted)onError(error);});
    return ()=>controller.abort();
  }
  const application=id=>{
    if(typeof id!=='string'||!/^[a-z][a-z0-9-]*$/.test(id))throw Error('Invalid application ID');
    return `/api/apps/${id}`;
  };
  return {
    authorizationState:()=>read('/api/authorization/state'),
    authorizationProgress:attempt=>{
      if(attempt!==undefined&&!/^[a-f0-9]{32}$/i.test(attempt))throw Error('Invalid authorization attempt');
      return read('/api/authorization/progress'+(attempt?`?attempt=${attempt}`:''));
    },
    applicationStatus:id=>read(application(id)+'/status'),
    applicationInstallation:id=>read(application(id)+'/installation'),
    applications:()=>read('/api/apps'),update:()=>read('/api/update'),subscribe,
  };
}
